import { createGlobalStyle } from "styled-components";

export const GlobalStyles = createGlobalStyle`
  *,
  *::after,
  *::before {
    box-sizing: border-box;
  }

  body {
    background: ${({ theme }) => theme.body};
    color: ${({ theme }) => theme.text};
    /* Block layout, not flex: as a flex item each page root shrink-wrapped to its
       own content width, so the header (and navbar) landed at a different x on
       every page. */
    display: block;
    font-family: BlinkMacSystemFont, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    transition: all 0.25s linear;
  }

  /* Reserve the scrollbar gutter so short pages don't shift the layout sideways. */
  html {
    overflow-y: scroll;
  }`;
