import React, { useEffect, useRef, useState } from "react";
import "./RotatingRole.css";

const TYPE_MS = 70;
const DELETE_MS = 35;
const HOLD_MS = 1600;

export default function RotatingRole({ roles, theme }) {
  const [index, setIndex] = useState(0);
  const [text, setText] = useState("");
  const [deleting, setDeleting] = useState(false);
  const timeout = useRef(null);

  useEffect(() => {
    const full = roles[index % roles.length];

    if (!deleting && text === full) {
      timeout.current = setTimeout(() => setDeleting(true), HOLD_MS);
    } else if (deleting && text === "") {
      setDeleting(false);
      setIndex((i) => (i + 1) % roles.length);
    } else {
      const next = deleting
        ? full.slice(0, text.length - 1)
        : full.slice(0, text.length + 1);
      timeout.current = setTimeout(
        () => setText(next),
        deleting ? DELETE_MS : TYPE_MS
      );
    }

    return () => clearTimeout(timeout.current);
  }, [text, deleting, index, roles]);

  // Reserve the width of the longest role so the line never reflows mid-type.
  const longest = roles.reduce((a, b) => (a.length >= b.length ? a : b), "");

  return (
    <h2 className="rotating-role" style={{ color: theme.text }}>
      <span className="rotating-role-sizer" aria-hidden="true">
        {longest}
      </span>
      <span className="rotating-role-text">
        <span aria-live="polite">{text}</span>
        <span
          className="rotating-role-cursor"
          style={{ backgroundColor: theme.imageHighlight }}
        />
      </span>
    </h2>
  );
}
