import React from "react";
import { Link } from "react-router-dom";
import "./Greeting.css";
import SocialMedia from "../../components/socialMedia/SocialMedia";
import Button from "../../components/button/Button";
import RotatingRole from "../../components/rotatingRole/RotatingRole";
import { greeting } from "../../portfolio";
import { Fade } from "react-reveal";

export default function Greeting(props) {
  const theme = props.theme;
  return (
    <Fade bottom duration={500} distance="40px">
      <div className="greet-main" id="greeting">
        <div className="greeting-main">
          <div className="greeting-text-div">
            <div>
              <h1 className="greeting-text" style={{ color: theme.text }}>
                {greeting.title}
              </h1>
              {greeting.roles && greeting.roles.length > 0 ? (
                <RotatingRole roles={greeting.roles} theme={theme} />
              ) : (
                greeting.nickname && (
                  <h2
                    className="greeting-nickname"
                    style={{ color: theme.text }}
                  >
                    ( {greeting.nickname} )
                  </h2>
                )
              )}
              <p
                className="greeting-text-p subTitle"
                style={{ color: theme.secondaryText }}
              >
                {greeting.subTitle}
              </p>
              <SocialMedia theme={theme} />
              <div className="button-greeting-div">
                <Button
                  text="See my resume"
                  newTab={true}
                  href={greeting.resumeLink}
                  theme={theme}
                />
                <Link
                  className="main-button greeting-secondary-btn"
                  to="/contact"
                  style={{
                    color: theme.text,
                    backgroundColor: "transparent",
                    border: `solid 1px ${theme.text}`,
                  }}
                >
                  Contact me
                </Link>
              </div>
            </div>
          </div>
          <div className="greeting-image-div">
            <img src={require(`../../assets/images/Portfolio.png`)} alt="" />
          </div>
        </div>
      </div>
    </Fade>
  );
}
